        fs.writeFileSync(serviceWorkerPath, swContent);
        console.log(`✅ Service worker updated with cache version: v-${buildTimestamp}`);
    } catch (error) {
        console.error(`❌ Error updating service worker: ${error.message}`);
    }
}

