    const isFullPayment = payment.amount >= itemsSubtotal;
    const paymentTypeLabel = isFullPayment ? 'Full Payment' : 
                             (displayIndex === 0 ? 'Deposit (35%)' : 'Partial Payment');

    const receiptHtml = `
