const { GEMINI_API_KEY } = process.env;

/**
 * Extracts a JSON object from a string, even if it's wrapped in markdown.
 * @param {string} text - The raw text response from the AI.
 * @returns {object} The parsed JSON object.
 */
function cleanAndParseGeminiJson(text) {
  console.log('[Debug] Raw Gemini Text:', text);
  const jsonMatch = text.match(/{[\s\S]*}/);
  if (!jsonMatch) {
    throw new Error('Gemini response did not contain a valid JSON object.');
  }
  const jsonString = jsonMatch[0];
  try {
    return JSON.parse(jsonString);
  } catch (parseError) {
    console.error('[Debug] Failed to parse extracted JSON:', parseError);
    throw new Error(`Failed to parse AI response as JSON: ${parseError.message}`);
  }
}

exports.handler = async (event) => {
  if (event.httpMethod !== 'POST') {
    return { statusCode: 405, body: JSON.stringify({ error: 'Method Not Allowed' }) };
  }

  if (!GEMINI_API_KEY) {
      console.error("CRITICAL: GEMINI_API_KEY is not set.");
      return { statusCode: 500, body: JSON.stringify({ error: 'Server configuration error.' }) };
  }

  try {
    const { query } = JSON.parse(event.body);
    if (!query) {
      return { statusCode: 400, body: JSON.stringify({ error: 'Missing "query" in request body.' }) };
    }

    console.log(`[process-weblink] Parsing query: ${query}`);

    const aiPrompt = `
      You are an expert event planner for the San Francisco Bay Area. A user has provided a URL or name for an activity, venue, or restaurant.
      Your task is to parse this query and respond ONLY with a valid JSON object. Do not include markdown \`\`\`json or any text before or after the JSON.
      The JSON object must have these fields:
      - "Name": The official name of the item (e.g., "Exploratorium After Dark").
      - "Description": A 1-2 sentence compelling description for an event plan.
      - "Price": An *estimated* price per person as a single number. Use 0 if it's free or the price is unknown/complex (like a full restaurant buyout).
      - "ServiceType": This should always be "Partner Activity".

      Example Query: "https://www.exploratorium.edu/after-dark"
      Example Response:
      {
        "Name": "Exploratorium After Dark",
        "Description": "A renowned hands-on museum of science and art, open for adults-only (18+) evenings with a cash bar and music.",
        "Price": 40,
        "ServiceType": "Partner Activity"
      }

      Example Query: "Hike at Mount Tamalpais"
      Example Response:
      {
        "Name": "Hike at Mount Tamalpais",
        "Description": "A scenic hike at Mt. Tamalpais State Park, offering stunning views of the Bay Area and the Pacific Ocean.",
        "Price": 0,
        "ServiceType": "Partner Activity"
      }
    `;

    console.log('[process-weblink] Sending data to Gemini API.');
    const geminiResponse = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent?key=${GEMINI_API_KEY}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        // Use the prompt and the user's query as two parts
        contents: [{ parts: [ { text: aiPrompt }, { text: `Query: "${query}"` } ] }]
      })
    });

    if (!geminiResponse.ok) {
      const errorBody = await geminiResponse.text();
      console.error('[process-weblink] Gemini API Error:', errorBody);
      throw new Error(`Gemini API request failed: ${errorBody}`);
    }

    const geminiResult = await geminiResponse.json();
    const geminiTextResponse = geminiResult?.candidates?.[0]?.content?.parts?.[0]?.text;

    if (!geminiTextResponse) {
      throw new Error('Could not find text in Gemini response.');
    }

    const extractedData = cleanAndParseGeminiJson(geminiTextResponse);
    console.log('[process-weblink] Success. Parsed data:', extractedData);

    // Return the JSON data for the new item
    return {
      statusCode: 200,
      body: JSON.stringify(extractedData),
    };

  } catch (error) {
    console.error('--- [process-weblink] FUNCTION FAILED ---');
    console.error('Error details:', error.message);
    return { statusCode: 500, body: JSON.stringify({ error: 'Failed to process web link: ' + error.message }) };
  }
};

// FILE: netlify/functions/profile-item.js
const fetch = require('node-fetch');
const { AIRTABLE_PAT, BASE_ID, GEMINI_API_KEY } = process.env;

const ITEMS_TABLE = 'tblUA4uuS8IYlhKpD'; // Main catalog table
const RANKINGS_FIELD = 'Rankings'; // The field to update
const NAME_FIELD = 'Name';
const DESCRIPTION_FIELD = 'Description';

/**
 * Extracts a JSON object from a string, even if it's wrapped in markdown.
 * @param {string} text - The raw text response from the AI.
 * @returns {object} The parsed JSON object.
 */
function cleanAndParseGeminiJson(text) {
  console.log('[Debug] Raw Gemini Text:', text);
  // Look for the first { and the last } to get the JSON block
  const jsonMatch = text.match(/{[\s\S]*}/);
  if (!jsonMatch) {
    throw new Error('Gemini response did not contain a valid JSON object.');
  }
  const jsonString = jsonMatch[0];
  try {
    return JSON.parse(jsonString);
  } catch (parseError) {
    console.error('[Debug] Failed to parse extracted JSON:', parseError);
    throw new Error(`Failed to parse AI response as JSON: ${parseError.message}`);
  }
}

/**
 * Calls the Gemini API to generate a "Universal Profile" for an item.
 * @param {string} itemName - The name of the item.
 * @param {string} itemDescription - The description of the item.
 * @returns {object} The parsed "Universal Profile" JSON object.
 */
async function getProfileFromGemini(itemName, itemDescription) {
    console.log(`[Debug] getProfileFromGemini: Profiling item: ${itemName}`);
    if (!GEMINI_API_KEY) {
        console.error("[Debug] CRITICAL: GEMINI_API_KEY is missing!");
        throw new Error("Server configuration error: Missing Gemini API Key.");
    }

    const prompt = `
      You are an expert event profiler for an event planning company.
      Based on this item's name and description, score it from 0 (none) to 10 (max) on the following attributes.
      Respond ONLY with a valid JSON object. Do not include markdown \`\`\`json or any text before or after the JSON.

      The JSON must have this exact structure:
      {
        "profileSource": "ai_v1_gemini_profile",
        "Pillars": { "Activities": 0, "Food/Drink": 0, "Venue": 0, "Extras": 0 },
        "Vibe": { "Energy": 0, "Relaxation": 0, "Formality": 0, "Novelty": 0 },
        "Intellect": { "Creative": 0, "Analytical": 0 },
        "Physicality": { "Intensity": 0, "Accessibility": 0 },
        "Tags": []
      }

      INSTRUCTIONS:
      1.  **Pillars:** Score 1-10 if the item *is* this thing (e.g., Go-Karts is "Activities": 10. A taco bar is "Food/Drink": 10). Most items are only one pillar.
      2.  **Vibe:** Score 0-10 for Energy (active) vs. Relaxation (calm), Formality (fancy) vs. Novelty (unique).
      3.  **Intellect/Physicality:** Score 0-10 for these attributes.
      4.  **Tags (CRITICAL):** Populate this array with lowercase string keywords.
          * **Attribute Tags:** Descriptive words (e.g., "competitive", "outdoor", "relaxing", "loud", "daytime").
          * **Concrete Noun Tags:** Specific keywords for content, theme, or category (e.g., "go-kart", "racing", "museum", "art", "science", "tacos", "mexican food", "bar").
    `;

    const payload = {
        contents: [
            {
                parts: [
                    { text: prompt },
                    { text: `Item Name: "${itemName}"\nItem Description: "${itemDescription || 'No description provided.'}"` }
                ]
            }
        ],
    };

    const apiUrl = `https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent?key=${GEMINI_API_KEY}`;

    console.log(`[Debug] getProfileFromGemini: Sending request to Gemini...`);
    const response = await fetch(apiUrl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    console.log(`[Debug] getProfileFromGemini: Received status ${response.status} from Gemini.`);

    if (!response.ok) {
        let errorBody = await response.text();
        console.error("[Debug] Gemini API Error Response Body:", errorBody);
        throw new Error(`Gemini API call failed with status ${response.status}`);
    }

    const result = await response.json();
    let jsonText = '';
    try {
        jsonText = result.candidates[0].content.parts[0].text;
    } catch (e) {
        console.error('[Debug] Error extracting text from Gemini response structure:', JSON.stringify(result, null, 2));
        throw new Error('Could not extract text from Gemini response.');
    }

    console.log(`[Debug] getProfileFromGemini: Received text response from Gemini.`);
    return cleanAndParseGeminiJson(jsonText); // This will parse and return the object
}

exports.handler = async (event) => {
    console.log(`[Debug] /api/profile-item handler invoked. Method: ${event.httpMethod}`);
    if (event.httpMethod !== 'POST') {
        return { statusCode: 405, body: JSON.stringify({ error: 'Method Not Allowed' }) };
    }

    try {
        const { recordId } = JSON.parse(event.body);
        if (!recordId) {
            return { statusCode: 400, body: JSON.stringify({ error: 'Missing recordId' }) };
        }

        console.log(`[Debug] Processing profile for record: ${recordId}`);

        // 1. Fetch the Item's Name and Description
        const fetchUrl = `https://api.airtable.com/v0/${BASE_ID}/${ITEMS_TABLE}/${recordId}?fields[]=${NAME_FIELD}&fields[]=${DESCRIPTION_FIELD}`;
        console.log(`[Debug] Fetching item details from: ${fetchUrl}`);
        const itemResponse = await fetch(fetchUrl, { headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` } });

        if (!itemResponse.ok) {
            console.error(`[Debug] Airtable fetch failed: ${itemResponse.status}`);
            throw new Error(`Failed to fetch item ${recordId} from Airtable. Status: ${itemResponse.statusText}`);
        }

        const itemRecord = await itemResponse.json();
        const itemName = itemRecord.fields[NAME_FIELD];
        const itemDescription = itemRecord.fields[DESCRIPTION_FIELD];

        if (!itemName) {
            console.warn(`[Debug] Item ${recordId} has no Name field. Aborting.`);
            return { statusCode: 400, body: JSON.stringify({ error: `Item ${recordId} has no name.` }) };
        }
         console.log(`[Debug] Fetched item. Name: ${itemName}`);

        // 2. Generate the Universal Profile via Gemini
        const profileJson = await getProfileFromGemini(itemName, itemDescription);
        console.log(`[Debug] AI profile generated for ${recordId}.`);

        // 3. Update the Item record in Airtable
        const patchUrl = `https://api.airtable.com/v0/${BASE_ID}/${ITEMS_TABLE}/${recordId}`;
        const payload = {
            fields: {
                [RANKINGS_FIELD]: JSON.stringify(profileJson, null, 2) // Pretty-print the JSON
            }
        };

        console.log(`[Debug] Patching Airtable record ${recordId}...`);
        const patchRes = await fetch(patchUrl, {
            method: 'PATCH',
            headers: {
                'Authorization': `Bearer ${AIRTABLE_PAT}`,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(payload)
        });

        if (!patchRes.ok) {
            const errorBody = await patchRes.text();
            console.error(`[Debug] Airtable patch failed. Status: ${patchRes.status}, Body: ${errorBody}`);
            throw new Error(`Failed to update Rankings for item ${recordId} in Airtable.`);
        }

        console.log(`[Debug] Successfully profiled and updated item ${recordId}.`);

        return {
            statusCode: 200,
            body: JSON.stringify({ success: true, recordId: recordId, profile: profileJson })
        };

    } catch (error) {
        console.error('[ERROR] /api/profile-item handler failed:', error.message, error.stack);
        return {
            statusCode: 500,
            body: JSON.stringify({ error: `Function execution failed: ${error.message}` })
        };
    }
};

// In netlify/functions/pusher-auth.js

const Pusher = require("pusher");

const pusher = new Pusher({
    appId: process.env.PUSHER_APP_ID,
    key: process.env.PUSHER_KEY,
    secret: process.env.PUSHER_SECRET,
    cluster: process.env.PUSHER_CLUSTER,
    useTLS: true,
});

exports.handler = async (event) => {
    if (event.httpMethod !== 'POST') {
        return { statusCode: 405, body: 'Method Not Allowed' };
    }

    // Use URLSearchParams to parse the form data from the event body
    const params = new URLSearchParams(event.body);
    const socketId = params.get('socket_id');
    const channel = params.get('channel_name');

    // The user data is passed directly from the client's auth config
    const presenceData = {
        user_id: params.get('user_id'),
        user_info: {
            name: params.get('user_name'),
        },
    };

    try {
        const authResponse = pusher.authorizeChannel(socketId, channel, presenceData);
        return {
            statusCode: 200,
            body: JSON.stringify(authResponse),
        };
    } catch (error) {
        console.error(error);
        return {
            statusCode: 500,
            body: JSON.stringify({ msg: 'Pusher authentication failed' }),
        };
    }
};

const fetch = require('node-fetch');
const sgMail = require('@sendgrid/mail');
const { generateICalContent, generateCalendarLinks } = require('./utils/ical-generator');

const AIRTABLE_PAT = process.env.AIRTABLE_PAT;
const BASE_ID = process.env.BASE_ID || 'app5yTznb3R5YNUFw';
const ITEMS_TABLE_NAME = 'Items';
const USERS_TABLE_NAME = 'Users';
const SENDGRID_API_KEY = process.env.SENDGRID_API_KEY;
const SITE_URL = process.env.SITE_URL || process.env.URL;

sgMail.setApiKey(SENDGRID_API_KEY);

exports.handler = async (event, context) => {
    if (event.httpMethod !== 'POST') {
        return {
            statusCode: 405,
            body: JSON.stringify({ error: 'Method not allowed' })
        };
    }

    const authHeader = event.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
        return {
            statusCode: 401,
            body: JSON.stringify({ error: 'Missing or invalid authorization token' })
        };
    }

    const token = authHeader.substring(7);
    let userId;
    try {
        const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
        if (payload.exp * 1000 < Date.now()) {
            return {
                statusCode: 401,
                body: JSON.stringify({ error: 'Token expired' })
            };
        }
        userId = payload.userId;
    } catch (error) {
        return {
            statusCode: 401,
            body: JSON.stringify({ error: 'Invalid token' })
        };
    }

    const { eventId, action } = JSON.parse(event.body);

    if (!eventId || !action) {
        return {
            statusCode: 400,
            body: JSON.stringify({ error: 'Missing eventId or action' })
        };
    }

    if (action !== 'add' && action !== 'remove') {
        return {
            statusCode: 400,
            body: JSON.stringify({ error: 'Invalid action. Must be "add" or "remove"' })
        };
    }

    try {
        const eventUrl = `https://api.airtable.com/v0/${BASE_ID}/${ITEMS_TABLE_NAME}/${eventId}`;

        const getResponse = await fetch(eventUrl, {
            headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` }
        });

        if (!getResponse.ok) {
            throw new Error(`Failed to fetch event: ${getResponse.statusText}`);
        }

        const eventRecord = await getResponse.json();

        if (eventRecord.fields['Item Type'] !== 'Event') {
            return {
                statusCode: 400,
                body: JSON.stringify({ error: 'Record is not an event' })
            };
        }

        let currentRsvps = eventRecord.fields.RSVPs || [];

        let updated = false;
        if (action === 'add' && !currentRsvps.includes(userId)) {
            currentRsvps.push(userId);
            updated = true;
        } else if (action === 'remove' && currentRsvps.includes(userId)) {
            currentRsvps = currentRsvps.filter(id => id !== userId);
            updated = true;
        }

        if (updated) {
            const patchResponse = await fetch(eventUrl, {
                method: 'PATCH',
                headers: {
                    'Authorization': `Bearer ${AIRTABLE_PAT}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    fields: {
                        RSVPs: currentRsvps
                    }
                })
            });

            if (!patchResponse.ok) {
                throw new Error(`Failed to update RSVPs: ${patchResponse.statusText}`);
            }

            if (action === 'add') {
                try {
                    const userUrl = `https://api.airtable.com/v0/${BASE_ID}/${USERS_TABLE_NAME}/${userId}`;
                    const userResponse = await fetch(userUrl, {
                        headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` }
                    });

                    if (userResponse.ok) {
                        const userRecord = await userResponse.json();
                        const userEmail = userRecord.fields.Email;
                        const userName = userRecord.fields.Name || 'there';

                        if (userEmail && eventRecord.fields.Date) {
                            const icalContent = generateICalContent(eventRecord);
                            const calendarLinks = generateCalendarLinks(eventRecord, SITE_URL);

                            const icalAttachment = Buffer.from(icalContent).toString('base64');

                            const eventName = eventRecord.fields.Name || 'Event';
                            const eventDate = new Date(eventRecord.fields.Date + 'T00:00:00').toLocaleDateString('en-US', {
                                weekday: 'long',
                                year: 'numeric',
                                month: 'long',
                                day: 'numeric'
                            });
                            const eventTime = eventRecord.fields.Time || '';

                            const msg = {
                                to: userEmail,
                                from: 'info@tylersmysterytours.com',
                                subject: `You're going to ${eventName}!`,
                                html: `
                                    <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
                                        <h2>Thanks for RSVPing!</h2>
                                        <p>Hi ${userName},</p>
                                        <p>You've successfully RSVP'd to <strong>${eventName}</strong>.</p>

                                        <div style="background: #f4f4f4; padding: 20px; border-radius: 8px; margin: 20px 0;">
                                            <h3 style="margin-top: 0;">Event Details</h3>
                                            <p><strong>📅 Date:</strong> ${eventDate}</p>
                                            ${eventTime ? `<p><strong>🕒 Time:</strong> ${eventTime}</p>` : ''}
                                            ${eventRecord.fields.Location ? `<p><strong>📍 Location:</strong> ${eventRecord.fields.Location}</p>` : ''}
                                        </div>

                                        <h3>Add to Your Calendar</h3>
                                        <p>Choose your preferred calendar app:</p>
                                        <div style="margin: 20px 0;">
                                            <a href="${calendarLinks.google}" style="display: inline-block; background: #4285F4; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px; margin: 5px;">Google Calendar</a>
                                            <a href="${calendarLinks.outlook}" style="display: inline-block; background: #0078D4; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px; margin: 5px;">Outlook</a>
                                            <a href="${calendarLinks.yahoo}" style="display: inline-block; background: #6001D2; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px; margin: 5px;">Yahoo</a>
                                        </div>

                                        <p style="color: #666; font-size: 14px;">An iCalendar (.ics) file is also attached to this email for easy import into any calendar application.</p>

                                        <p>See you there!</p>
                                        <p>- The WhatTheFunFinder Team</p>
                                    </div>
                                `,
                                attachments: [
                                    {
                                        content: icalAttachment,
                                        filename: `${eventName.replace(/[^a-z0-9]/gi, '_')}.ics`,
                                        type: 'text/calendar',
                                        disposition: 'attachment'
                                    }
                                ]
                            };

                            await sgMail.send(msg);
                            console.log(`RSVP confirmation email sent to ${userEmail}`);
                        }
                    }
                } catch (emailError) {
                    console.error('Failed to send RSVP confirmation email:', emailError);
                }
            }
        }

        return {
            statusCode: 200,
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                success: true,
                rsvped: action === 'add',
                rsvpCount: currentRsvps.length
            })
        };
    } catch (error) {
        console.error('RSVP error:', error);
        return {
            statusCode: 500,
            body: JSON.stringify({ error: 'Failed to process RSVP' })
        };
    }
};

